package com.gomgomapps.math.core;
import java.math.*;import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class GradeSevenFractionDecimalRecallScopeTest {
 private static final String SYSTEM="na-nied-primary-2024-v1",ID=FractionDecimalRecall.ID;
 @Test public void normalNaSevenDirectRecallStaysTypedWithBalancedFreshFamiliesAndAllThirtyEightOriginals(){
  var pack=GlobalCurriculum.packs("NA").stream().filter(p->p.id.equals(SYSTEM)).findFirst().orElseThrow();assertTrue(pack.inGrade(ID,7));assertFalse(pack.inGrade(ID,6));assertEquals(1,Catalog.ALL.stream().filter(s->s.id.equals(ID)).count());assertEquals("분수·소수 대응값",Catalog.get(ID).title);CurriculumLimits limits=GlobalCurriculum.limits(SYSTEM,ID,7);
  for(boolean multipleChoice:List.of(false,true)){Generator gen=new Generator(new Random(360));List<String> recent=new ArrayList<>();Set<Integer> denominators=new HashSet<>();Set<Integer> firstFamilies=new HashSet<>();boolean zero=false,whole=false,unreduced=false;
   for(int i=0;i<38;i++){Question q=gen.next(ID,recent,multipleChoice,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());var g=FractionDecimalRecall.read(q);assertNotNull(g);assertTrue(limits.allows(q));denominators.add(g.denominator().intValueExact());if(i<3)firstFamilies.add(!g.finitePossible()?0:g.denominator().equals(BigInteger.valueOf(8))&&g.numerator().testBit(0)?1:2);zero|=g.value().equals(Rational.ZERO);whole|=g.value().equals(Rational.ONE);unreduced|=g.numerator().signum()>0&&!g.numerator().gcd(g.denominator()).equals(BigInteger.ONE);assertEquals("exactDecimalRecall",q.kind);assertTrue(q.choices.isEmpty());assertTrue(q.choiceLabels.isEmpty());assertEquals(-1,q.correctChoice);assertFalse(FractionInput.available(q));assertEquals(4,HelpPlan.forQuestion(q).size());assertFalse(HelpPlan.forQuestion(q).canTransfer());assertTrue(new Checker().check(q,List.of(),List.of(q.answers[0])).correct());}
   assertEquals(Set.of(2,3,4,5,8,10),denominators);assertEquals(Set.of(0,1,2),firstFamilies);assertTrue(zero&&whole&&unreduced);assertEquals(recent.get(0),gen.next(ID,recent,multipleChoice,limits).signature());
  }
 }
 @Test public void declaredSupplyFiltersUsePublicFractionAndDoNotConstrainGeneralExactRecall(){
  Question q=new Question(ID,FractionDecimalRecall.prompt("1","3"),"-999.123456789","999");q.studyGuide=new StudyGuide().step("private","private","","999");StudyGuide stored=q.studyGuide;CurriculumLimits limits=GlobalCurriculum.limits(SYSTEM,ID,7);assertTrue(limits.allows(q));q.expression=null;q.answers=null;assertTrue(limits.allows(q));assertTrue(new CurriculumLimits("decimalPlaces=1;nonnegative=true").allows(q));assertFalse(new CurriculumLimits("maxResult=0.3").allows(q));assertFalse(new CurriculumLimits("answerDecimalPlaces=3").allows(q));assertTrue(new CurriculumLimits("unitFractions=true").allows(q));assertEquals(4,HelpPlan.forQuestion(q).size());assertSame(stored,q.studyGuide);assertNull(q.expression);assertNull(q.answers);
  Question outside=new Question(ID,FractionDecimalRecall.prompt("4","7"),null,"");assertNotNull(FractionDecimalRecall.read(outside));assertFalse(limits.allows(outside));assertTrue(CurriculumLimits.NONE.allows(outside));assertTrue(new Checker().check(outside,List.of(),List.of("0.(571428)")).correct());Question large=new Question(ID,FractionDecimalRecall.prompt("1","99999999999999999989"),null,"");assertFalse(limits.allows(large));assertTrue(CurriculumLimits.NONE.allows(large));
 }
 @Test public void oldRoundedDivisionReverseReductionAndNaSixComparisonContractsRemainUnchanged(){
  Question rounded=new Question(FractionToDecimalCheck.ID,FractionDecimalDivision.prompt("1","3"),"poison","999");assertTrue(new Checker().check(rounded,List.of(),List.of("0.333")).correct());assertFalse(new Checker().check(rounded,List.of(),List.of("0.(3)")).correct());assertEquals(23,HelpPlan.forQuestion(rounded).size());assertFalse(HelpPlan.forQuestion(rounded).canTransfer());
  Question reduced=DecimalToFractionSupply.makeReduced(0,45,2);assertTrue(new Checker().check(reduced,List.of(),List.of("9/20")).correct());assertEquals("약분 필요",new Checker().check(reduced,List.of(),List.of("45/100")).message);assertEquals(7,HelpPlan.forQuestion(reduced).size());Question plain=DecimalToFractionSupply.make(0,45,2);assertEquals(4,HelpPlan.forQuestion(plain).size());assertTrue(new Checker().check(plain,List.of(),List.of("45/100")).correct());assertEquals(2,GlobalCurriculum.limits(SYSTEM,DecimalToFractionSupply.ID,6).decimalPlaces(1));
  Question comparison=FractionDecimalComparison.make(1,2,50,true);assertEquals(5,HelpPlan.forQuestion(comparison).size());assertTrue(new Checker().check(comparison,List.of(),List.of("=")).correct());assertFalse(FractionDecimalComparison.DENOMINATORS.contains(3));assertEquals("분수와 소수의 값 비교",Catalog.get(FractionDecimalComparison.ID).title);
 }
}
